CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'cliente' CHECK(role IN ('admin','empleado','cliente')),phone TEXT DEFAULT '',document TEXT DEFAULT '',billing TEXT DEFAULT '{}',consent_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,parent_id INTEGER REFERENCES categories(id),image TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS brands(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY,brand TEXT NOT NULL,model TEXT NOT NULL,year INTEGER NOT NULL,version TEXT NOT NULL,tipo_vehiculo TEXT NOT NULL DEFAULT 'auto',UNIQUE(brand,model,year,version));
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,brand_id INTEGER NOT NULL REFERENCES brands(id),category_id INTEGER NOT NULL REFERENCES categories(id),price_cents INTEGER NOT NULL CHECK(price_cents>0),cost_cents INTEGER NOT NULL CHECK(cost_cents>=0),old_price_cents INTEGER NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=stock),minimum INTEGER NOT NULL DEFAULT 5 CHECK(minimum>=0),universal INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,featured INTEGER NOT NULL DEFAULT 0,oem TEXT NOT NULL DEFAULT '',specs TEXT NOT NULL DEFAULT '{}',description TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS compatibility(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,brand TEXT NOT NULL,model TEXT NOT NULL,year_from INTEGER NOT NULL,year_to INTEGER NOT NULL,version TEXT NOT NULL DEFAULT '',CHECK(year_to>=year_from));
CREATE TABLE IF NOT EXISTS product_images(id INTEGER PRIMARY KEY,product_id INTEGER REFERENCES products(id) ON DELETE CASCADE,url TEXT NOT NULL,thumb TEXT NOT NULL,source_url TEXT NOT NULL DEFAULT '',is_primary INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS garage(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),vehicle_id INTEGER REFERENCES vehicles(id),active INTEGER DEFAULT 0,UNIQUE(user_id,vehicle_id));
CREATE TABLE IF NOT EXISTS addresses(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),label TEXT NOT NULL,street TEXT NOT NULL,ubigeo TEXT NOT NULL,reference TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS ubigeo(code TEXT PRIMARY KEY,department TEXT NOT NULL,province TEXT NOT NULL,district TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotes(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,user_id INTEGER REFERENCES users(id),guest_token TEXT NOT NULL,customer_name TEXT NOT NULL,total_cents INTEGER NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'vigente',order_id INTEGER);
CREATE TABLE IF NOT EXISTS quote_items(id INTEGER PRIMARY KEY,quote_id INTEGER REFERENCES quotes(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),price_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,user_id INTEGER REFERENCES users(id),guest_token TEXT NOT NULL,customer_name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,document_type TEXT NOT NULL,document TEXT NOT NULL,business_name TEXT DEFAULT '',delivery TEXT NOT NULL,address TEXT DEFAULT '',ubigeo TEXT DEFAULT '',shipping_zone TEXT DEFAULT '',shipping_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,base_cents INTEGER NOT NULL,tax_cents INTEGER NOT NULL,status TEXT NOT NULL,payment_method TEXT NOT NULL,actor TEXT NOT NULL DEFAULT 'usuario',created_at TEXT NOT NULL,expires_at TEXT NOT NULL,paid_at TEXT,tracking TEXT DEFAULT '',idempotency_key TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),product_id INTEGER REFERENCES products(id),sku TEXT NOT NULL,name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),price_cents INTEGER NOT NULL,cost_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL UNIQUE REFERENCES orders(id),method TEXT NOT NULL,amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pendiente',voucher TEXT DEFAULT '',note TEXT DEFAULT '',verified_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL,verified_at TEXT);
CREATE TABLE IF NOT EXISTS order_history(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',user_id INTEGER REFERENCES users(id),actor TEXT DEFAULT 'usuario',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_movements(id INTEGER PRIMARY KEY,product_id INTEGER REFERENCES products(id),kind TEXT NOT NULL,quantity INTEGER NOT NULL,reserved_delta INTEGER NOT NULL DEFAULT 0,balance INTEGER NOT NULL,reason TEXT NOT NULL,order_id INTEGER REFERENCES orders(id),user_id INTEGER REFERENCES users(id),actor TEXT NOT NULL CHECK(actor IN ('usuario','sistema','agente')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,ruc TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,contact TEXT DEFAULT '',active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS purchase_orders(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,supplier_id INTEGER REFERENCES suppliers(id),status TEXT NOT NULL DEFAULT 'pendiente',total_cents INTEGER NOT NULL,actor TEXT NOT NULL DEFAULT 'usuario',user_id INTEGER REFERENCES users(id),created_at TEXT NOT NULL,received_at TEXT);
CREATE TABLE IF NOT EXISTS purchase_items(id INTEGER PRIMARY KEY,purchase_order_id INTEGER REFERENCES purchase_orders(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),cost_cents INTEGER NOT NULL CHECK(cost_cents>=0));
CREATE TABLE IF NOT EXISTS complaints(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE,user_id INTEGER REFERENCES users(id),name TEXT NOT NULL,email TEXT NOT NULL,document TEXT NOT NULL,phone TEXT NOT NULL,type TEXT NOT NULL,order_code TEXT DEFAULT '',detail TEXT NOT NULL,request TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pendiente',response TEXT DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,type TEXT NOT NULL,product_id INTEGER REFERENCES products(id),vehicle_id INTEGER REFERENCES vehicles(id),user_id INTEGER REFERENCES users(id),session_id TEXT NOT NULL,payload TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY,product_id INTEGER UNIQUE REFERENCES products(id),type TEXT NOT NULL DEFAULT 'stock_bajo',message TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'activa',created_at TEXT NOT NULL,resolved_at TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,entity TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,user_id INTEGER REFERENCES users(id),actor TEXT NOT NULL DEFAULT 'usuario',detail TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_stock(id INTEGER PRIMARY KEY,product_id INTEGER REFERENCES products(id),date TEXT NOT NULL,stock INTEGER NOT NULL,demand INTEGER NOT NULL,stockout INTEGER NOT NULL DEFAULT 0,UNIQUE(product_id,date));
CREATE INDEX IF NOT EXISTS idx_orders_date ON orders(created_at);
CREATE INDEX IF NOT EXISTS idx_events_date ON events(created_at,type);
CREATE INDEX IF NOT EXISTS idx_movement_product ON inventory_movements(product_id,created_at);
CREATE INDEX IF NOT EXISTS idx_compatibility ON compatibility(product_id,brand,model,year_from,year_to);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id,active);
